class API {
  async authenticate(token) {
    try {
      const response = await fetch('https://imvu.js.org/api/authenticate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': token,
        },
      });
      if (!response.ok) {
        throw new Error('Authentication failed');
      }
      const data = await response.json();

      if (data.v > 0.3) console.warn(data.vu);

      return data;
    } catch (error) {
      console.error('Authentication error:', error);
      throw new Error('Authentication failed');
    }
  }

}

module.exports = API;
